cov_a = values('W1::Coverage', 'D804:D813')
provider_areas = {}
for p, a in zip(cov_p, cov_a):
    if p not in provider_areas:
        provider_areas[p] = set()
    provider_areas[p].add(a)
required_areas = set(values('W1::Required', 'C42:C45'))
min_cost = 999999
for r in range(1, len(prov_names) + 1):
    for combo in itertools.combinations(prov_names, r):
        covered = set()
        total_cost = 0
        for p in combo:
            total_cost += costs.get(p, 0)
            if p in provider_areas:
                covered.update(provider_areas[p])
        if required_areas.issubset(covered):
            if total_cost < min_cost:
                min_cost = total_cost
result = int(min_cost)

